for u in range(5):
    for v in range(5, 10):
        edges.append((u, v))
print(edges)
print(len(edges))

# Verify triangle-free
edges_set = set(edges)
triangle_free = True
for u in range(10):
    for v in range(u+1, 10):
        for w in range(v+1, 10):
            if (u,v) in edges_set and (u,w) in edges_set and (v,w) in edges_set:
                triangle_free = False
                print(f"Triangle found: {u},{v},{w}")
print(f"Triangle-free: {triangle_free}")

# Verify maximal - check all missing edges
missing_edges = []
for u in range(10):
    for v in range(u+1, 10):
        if (u,v) not in edges_set:
            missing_edges.append((u,v))
print(f"Missing edges: {missing_edges}")

# For each missing edge, check if adding it creates a triangle
for (u,v) in missing_edges:
    creates_triangle = False
    for w in range(10):
        if w != u and w != v:
            if ((u,w) in edges_set or (w,u) in edges_set) and ((v,w) in edges_set or (w,v) in edges_set):
                creates_triangle = True
                break
    if not creates_triangle:
        print(f"Edge ({u},{v}) does NOT create a triangle - graph is not maximal!")
    else:
        print(f"Edge ({u},{v}) creates a triangle - good")

